# WAR ARENA - Hide exact formula weights (show methodology, not the secret sauce)
# The engine still runs the precise weighted formulas on the SERVER (never sent to
# the browser). Only the displayed description changes: methodology, not the numbers.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-hide-formulas.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - hide formula weights installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/analysis/warIndices.ts" ""

npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
npm run build; if ($LASTEXITCODE -ne 0){ throw "build failed" }
Write-Host ""; Write-Host "Done. Formula weights are now hidden (methodology shown instead). 1083 tests expected." -ForegroundColor Green
Write-Host "Restart: npm start" -ForegroundColor Yellow
